#!/usr/bin/env python3
"""
itesco_parser.py
Dynamicky vyhledá a vytěží aktuální leták pro Tesco Supermarket Rajhrad přes Publitas/itesco.cz.
"""

import concurrent.futures
from datetime import datetime, timezone
import json
import re
import sys
from typing import Any, Dict, List, Optional
from urllib.parse import urljoin, urlparse

from bs4 import BeautifulSoup
import requests

HEADERS = {
    "User-Agent": (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/124.0.0.0 Safari/537.36"
    ),
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,application/json,*/*;q=0.8",
    "Accept-Language": "cs-CZ,cs;q=0.9,en;q=0.8",
    "Referer": "https://itesco.cz/",
}

STORE_URL = "https://itesco.cz/prodejny/detail/rajhrad/"
FLYERS_CATALOG_URL = "https://itesco.cz/akce-a-letaky/letaky/"


def get_session() -> requests.Session:
    session = requests.Session()
    session.headers.update(HEADERS)
    return session


def check_url_status(url: str, session: requests.Session) -> Optional[int]:
    """Ověří, zda URL vrací HTTP 200."""
    if not url:
        return None
    try:
        response = session.head(url, allow_redirects=True, timeout=5)
        if response.status_code == 405:  # Method Not Allowed -> zkusit GET
            response = session.get(url, allow_redirects=True, stream=True, timeout=5)
        return response.status_code
    except requests.RequestException:
        return None


def find_flyer_url(session: requests.Session) -> Optional[str]:
    """
    Vyhledá odkaz na leták pro Rajhrad (prioritně Supermarket).
    1. Prohledá přímo stránku pobočky Rajhrad.
    2. Pokud nenalezeno, prohledá katalog letáků Tesco a vybere leták pro Supermarkety.
    """
    # 1. Kontrola detailu prodejny
    try:
        resp = session.get(STORE_URL, timeout=10)
        if resp.status_code == 200:
            soup = BeautifulSoup(resp.text, "html.parser")
            for link in soup.find_all(["a", "iframe"], href=True):
                href = link.get("href") or link.get("src")
                if "publitas.com" in href:
                    return href
    except requests.RequestException:
        pass

    # 2. Kontrola katalogu letáků
    try:
        resp = session.get(FLYERS_CATALOG_URL, timeout=10)
        if resp.status_code == 200:
            soup = BeautifulSoup(resp.text, "html.parser")
            links = soup.find_all("a", href=True)

            publitas_links = []
            for a in links:
                href = a.get("href", "")
                text = (a.get_text() + " " + href).lower()
                if "publitas.com" in href or "/letaky/" in href:
                    publitas_links.append((href, text))

            # Priorita pro Rajhrad: jedná se o 'Supermarket' (nikoli Hypermarket)
            for href, text in publitas_links:
                if "supermarket" in text:
                    return href if href.startswith("http") else urljoin(FLYERS_CATALOG_URL, href)

            # Záložní varianta: první dostupný leták
            if publitas_links:
                first_href = publitas_links[0][0]
                return first_href if first_href.startswith("http") else urljoin(FLYERS_CATALOG_URL, first_href)
    except requests.RequestException:
        pass

    return None


def extract_publitas_data(flyer_url: str, session: requests.Session) -> Dict[str, Any]:
    """
    Stáhne Publitas leták a extrahuje konfiguraci publikace, počet stránek a hotspoty/produkty.
    """
    resp = session.get(flyer_url, timeout=10)
    if resp.status_code != 200:
        raise ValueError(f"Nelze načíst leták z URL: {flyer_url} (HTTP {resp.status_code})")

    html_content = resp.text
    base_url = f"{urlparse(resp.url).scheme}://{urlparse(resp.url).netloc}"
    path_parts = [p for p in urlparse(resp.url).path.split("/") if p]

    # Pokus o extrakci JSON konfigurace přímo z HTML skriptů
    pub_data = None

    # Hledání window.publication nebo podobných proměnných
    patterns = [
        r"window\s*\[\s*['\"]publication['\"]\s*\]\s*=\s*({.+?});\s*<\/script>",
        r"var\s+publication\s*=\s*({.+?});",
        r"window\.publicationConfig\s*=\s*({.+?});",
        r"publicationConfig\s*=\s*({.+?});",
    ]

    for pattern in patterns:
        match = re.search(pattern, html_content, re.DOTALL)
        if match:
            try:
                pub_data = json.loads(match.group(1))
                break
            except json.JSONDecodeError:
                continue

    # Pokud není přímo v HTML, Publitas nabízí standardní JSON API dle slugů
    if not pub_data and len(path_parts) >= 2:
        group_slug = path_parts[0]
        pub_slug = path_parts[1]
        api_url = f"{base_url}/{group_slug}/{pub_slug}/pages.json"
        api_resp = session.get(api_url, timeout=10)
        if api_resp.status_code == 200:
            try:
                pages_json = api_resp.json()
                pub_data = {"pages": pages_json}
            except json.JSONDecodeError:
                pass

    return {
        "html": html_content,
        "json_data": pub_data,
        "final_url": resp.url,
    }


def parse_products_and_meta(flyer_data: Dict[str, Any], session: requests.Session) -> Dict[str, Any]:
    """
    Parsuje strukturované informace o letáku a reálné produkty.
    """
    html = flyer_data["html"]
    data = flyer_data.get("json_data") or {}
    final_url = flyer_data["final_url"]

    soup = BeautifulSoup(html, "html.parser")

    # Zjištění názvu a metadat
    title_tag = soup.find("title")
    title = title_tag.get_text(strip=True) if title_tag else "Tesco Leták"

    # Zjištění počtu stránek
    total_pages = 0
    pages = data.get("pages") or data.get("spreads") or []
    if pages:
        total_pages = len(pages)
    else:
        # Fallback z HTML / OpenGraph
        page_matches = re.findall(r'["\']numberOfPages["\']:\s*(\d+)', html)
        if page_matches:
            total_pages = int(page_matches[0])
        else:
            page_tags = soup.find_all(attrs={"data-page-number": True})
            if page_tags:
                total_pages = max(int(t["data-page-number"]) for t in page_tags)

    raw_products = []

    # Publitas ukládá hotspoty do stránek/spreadů
    if isinstance(pages, list):
        for idx, page in enumerate(pages, start=1):
            page_num = page.get("page_number", idx) if isinstance(page, dict) else idx
            hotspots = page.get("hotspots", []) if isinstance(page, dict) else []

            for hs in hotspots:
                # Zajímají nás produktové nebo odkazové hotspoty s informacemi
                p_title = hs.get("title") or hs.get("name")
                if not p_title:
                    continue

                prod_url = hs.get("webshop_url") or hs.get("url") or hs.get("link")
                price = hs.get("price") or hs.get("discount_price") or ""
                original_price = hs.get("original_price") or hs.get("regular_price") or ""
                description = hs.get("description") or ""
                image_url = hs.get("image_url") or hs.get("imageUrl") or ""

                raw_products.append({
                    "title": p_title.strip(),
                    "description": description.strip(),
                    "price": str(price).strip(),
                    "original_price": str(original_price).strip(),
                    "page": page_num,
                    "product_url": prod_url,
                    "image_url": image_url,
                })

    # Ověření dostupnosti produktových URL (HTTP 200)
    verified_products = []

    def verify_product(prod: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        url = prod.get("product_url")
        if url:
            status = check_url_status(url, session)
            prod["url_status"] = status
            if status != 200:
                # Pokud URL selže, vyřadíme neplatné URL nebo produkt
                return None
        else:
            prod["url_status"] = None
        return prod

    if raw_products:
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as executor:
            results = executor.map(verify_product, raw_products)
            for res in results:
                if res is not None:
                    verified_products.append(res)

    result_json = {
        "meta": {
            "store": "Tesco Supermarket Rajhrad",
            "flyer_title": title,
            "flyer_url": final_url,
            "total_pages": total_pages,
            "scraped_at": datetime.now(timezone.utc).isoformat(),
        },
        "products": verified_products,
    }

    return result_json


def main():
    session = get_session()
    output: Dict[str, Any] = {
        "meta": {
            "store": "Tesco Supermarket Rajhrad",
            "flyer_title": None,
            "flyer_url": None,
            "total_pages": 0,
            "scraped_at": datetime.now(timezone.utc).isoformat(),
            "error": None,
        },
        "products": [],
    }

    try:
        flyer_url = find_flyer_url(session)
        if not flyer_url:
            output["meta"]["error"] = "Nepodařilo se dynamicky dohledat odkaz na aktuální leták pro Rajhrad."
            print(json.dumps(output, ensure_ascii=False, indent=2))
            return

        flyer_data = extract_publitas_data(flyer_url, session)
        parsed_result = parse_products_and_meta(flyer_data, session)
        print(json.dumps(parsed_result, ensure_ascii=False, indent=2))

    except Exception as e:
        output["meta"]["error"] = f"Chyba při scrapingu: {str(e)}"
        print(json.dumps(output, ensure_ascii=False, indent=2))
        sys.exit(1)


if __name__ == "__main__":
    main()
